```typescript
import { type Request, type Response, Router } from 'express';
import { db } from '../db';

export const ordersRouter = Router();

ordersRouter.get('/', async (req: Request, res: Response) => {
  // Cursor pagination for orders endpoint
  const { cursor } = req.query;
  const limit = 50; // Number of orders to return at a time
  const params: any[] = [limit];
  let sql = `
    SELECT *
    FROM orders
    ORDER BY created_at DESC
    LIMIT $1
  `;

  if (cursor) {
    sql = `
      SELECT *
      FROM orders
      WHERE created_at < (SELECT created_at FROM orders WHERE order_id = $2)
      ORDER BY created_at DESC
      LIMIT $1
    `;
    params.push(cursor);
  }

  try {
    const { rows } = await db.query(sql, params);
    if (rows.length === 0) {
      return res.json({ orders: [], next_cursor: null });
    }
    const next_cursor = rows[rows.length - 1].order_id;
    res.json({ orders: rows, next_cursor });
  } catch (error) {
    console.error('Error fetching orders:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

